/**
 * SOURX Official Email Signature — Interactive Generator & Copy Controller
 * Allows real-time customization and one-click rich-text / HTML clipboard export.
 */

import '../css/main.css';
import '../css/email-signatures.css';

document.addEventListener('DOMContentLoaded', () => {
  initSignatureGenerator();
  initMobileDrawer();
});

/**
 * Mobile Drawer Menu Controller
 */
function initMobileDrawer() {
  const hamburger = document.querySelector('.advisano-hamburger-btn');
  const drawer = document.getElementById('advisano-mobile-menu');
  const closeBtn = document.querySelector('.advisano-drawer-close');

  if (!hamburger || !drawer) return;

  hamburger.addEventListener('click', () => {
    drawer.classList.add('active');
    document.body.style.overflow = 'hidden';
  });

  if (closeBtn) {
    closeBtn.addEventListener('click', () => {
      drawer.classList.remove('active');
      document.body.style.overflow = '';
    });
  }

  drawer.addEventListener('click', (e) => {
    if (e.target === drawer) {
      drawer.classList.remove('active');
      document.body.style.overflow = '';
    }
  });
}

/**
 * Live Signature Generator & Clipboard Controller
 */
function initSignatureGenerator() {
  const inputName = document.getElementById('inputName');
  const inputRole = document.getElementById('inputRole');
  const inputEmail = document.getElementById('inputEmail');
  const inputPhone = document.getElementById('inputPhone');
  const inputWebsite = document.getElementById('inputWebsite');
  const inputAddress = document.getElementById('inputAddress');

  const dispName = document.getElementById('dispName');
  const dispRole = document.getElementById('dispRole');
  const dispEmail = document.getElementById('dispEmail');
  const dispPhone = document.getElementById('dispPhone');
  const dispWebsite = document.getElementById('dispWebsite');
  const dispAddress = document.getElementById('dispAddress');
  const dispLogoImg = document.getElementById('dispLogoImg');
  const sigRightCell = document.getElementById('sigRightCell');
  const dispLinkWhatsapp = document.getElementById('dispLinkWhatsapp');

  const dispMobileName = document.getElementById('dispMobileName');
  const dispMobileRole = document.getElementById('dispMobileRole');
  const dispMobileEmail = document.getElementById('dispMobileEmail');
  const dispMobilePhone = document.getElementById('dispMobilePhone');
  const dispMobileWeb = document.getElementById('dispMobileWeb');
  const dispMobileAddress = document.getElementById('dispMobileAddress');
  const dispMobileLogoImg = document.getElementById('dispMobileLogoImg');
  const dispMobileRecipient = document.getElementById('dispMobileRecipient');
  const sigMobileBottomBlock = document.getElementById('sigMobileBottomBlock');

  const btnCopyVisual = document.getElementById('btnCopyVisual');
  const btnCopyHtml = document.getElementById('btnCopyHtml');
  const btnReset = document.getElementById('btnReset');
  const copyFeedback = document.getElementById('copyFeedback');
  const signatureWrap = document.getElementById('sourxOfficialSignature');
  const colorNameLabel = document.getElementById('colorNameLabel');

  if (!signatureWrap) return;

  const defaultValues = {
    name: 'Marc Gounon',
    role: 'Chef Département Audit',
    email: 'marc.gounon@sourx.com',
    phone: '+44 2081239177',
    website: 'www.sourx.com',
    address: 'London • Castellón • Cotonou',
    color: '#012e5c',
    colorName: 'Bleu Marine SOURX Officiel (#012e5c)',
    logo: 'monogram'
  };

  let currentColor = defaultValues.color;
  let currentLogo = defaultValues.logo;

  const logoMap = {
    minimal: '/images/signature/sourx-logo-sig-minimal.png',
    tagline: '/images/signature/sourx-logo-sig-tagline.png',
    monogram: '/images/signature/sourx-logo-sig-monogram.png'
  };

  const BASE64_ICONS = {
    monogram: "data:image/png;base64,",
    tagline: "data:image/png;base64,",
    minimal: "data:image/png;base64,",
    linkedin: "data:image/svg+xml;base64,",
    website: "data:image/svg+xml;base64,",
    twitter: "data:image/svg+xml;base64,",
    whatsapp: "data:image/svg+xml;base64,",
    email_white: "data:image/png;base64,",
    phone_white: "data:image/png;base64,",
    website_white: "data:image/png;base64,",
    location_white: "data:image/png;base64,",
  };

  const colorLabels = {
    '#012e5c': 'Bleu Marine SOURX Officiel (#012e5c)',
    '#2563eb': 'Bleu Royal Vibrant (Style Référence - #2563eb)',
    '#0b192c': 'Bleu Nuit Profond (#0b192c)',
    '#0c3b5e': 'Bleu Pétrole Executive (#0c3b5e)'
  };

  function updateDisplay() {
    const nameVal = inputName?.value.trim() || defaultValues.name;
    const roleVal = inputRole?.value.trim() || defaultValues.role;
    const emailVal = inputEmail?.value.trim() || defaultValues.email;
    const phoneVal = inputPhone?.value.trim() || defaultValues.phone;
    const webVal = inputWebsite?.value.trim() || defaultValues.website;
    const addrVal = inputAddress?.value.trim() || defaultValues.address;

    // Desktop
    if (dispName) dispName.textContent = nameVal;
    if (dispRole) dispRole.textContent = roleVal;
    
    if (dispEmail) {
      dispEmail.textContent = emailVal;
      dispEmail.href = `mailto:${emailVal}`;
    }
    if (dispPhone) {
      dispPhone.textContent = phoneVal;
      dispPhone.href = `tel:${phoneVal.replace(/\s+/g, '')}`;
    }
    if (dispWebsite) {
      dispWebsite.textContent = webVal;
      dispWebsite.href = webVal.startsWith('http') ? webVal : `https://${webVal}`;
    }
    if (dispAddress) {
      dispAddress.textContent = addrVal;
    }
    if (dispLinkWhatsapp) {
      const cleanPhone = phoneVal.replace(/[^0-9]/g, '');
      dispLinkWhatsapp.href = `https://wa.me/${cleanPhone || '442081239177'}`;
    }

    // Color application
    if (sigRightCell) {
      sigRightCell.style.backgroundColor = currentColor;
    }
    if (sigMobileBottomBlock) {
      sigMobileBottomBlock.style.backgroundColor = currentColor;
    }
    if (colorNameLabel) {
      colorNameLabel.innerHTML = `Nuance : <strong>${colorLabels[currentColor] || currentColor}</strong>`;
    }

    // Logo declination
    const logoSrc = logoMap[currentLogo] || logoMap.minimal;
    if (dispLogoImg) dispLogoImg.src = logoSrc;
    if (dispMobileLogoImg) dispMobileLogoImg.src = logoSrc;

    // Mobile Preview
    if (dispMobileName) dispMobileName.textContent = nameVal;
    if (dispMobileRole) dispMobileRole.textContent = roleVal;
    if (dispMobileEmail) {
      dispMobileEmail.textContent = emailVal;
      dispMobileEmail.href = `mailto:${emailVal}`;
    }
    if (dispMobilePhone) {
      dispMobilePhone.textContent = phoneVal;
      dispMobilePhone.href = `tel:${phoneVal.replace(/\s+/g, '')}`;
    }
    if (dispMobileWeb) {
      dispMobileWeb.textContent = webVal;
      dispMobileWeb.href = webVal.startsWith('http') ? webVal : `https://${webVal}`;
    }
    if (dispMobileAddress) {
      dispMobileAddress.textContent = addrVal;
    }
    if (dispMobileRecipient) {
      dispMobileRecipient.textContent = emailVal;
    }
  }

  // Live input synchronization
  [inputName, inputRole, inputEmail, inputPhone, inputWebsite, inputAddress].forEach(input => {
    if (input) {
      input.addEventListener('input', updateDisplay);
    }
  });

  // Logo declination selector buttons
  const logoPillButtons = document.querySelectorAll('.sig-pill-btn');
  logoPillButtons.forEach(btn => {
    btn.addEventListener('click', () => {
      logoPillButtons.forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      currentLogo = btn.getAttribute('data-logo-declination') || 'minimal';
      updateDisplay();
    });
  });

  // Color Swatches
  const colorSwatches = document.querySelectorAll('.sig-swatch');
  colorSwatches.forEach(swatch => {
    swatch.addEventListener('click', () => {
      colorSwatches.forEach(s => s.classList.remove('active'));
      swatch.classList.add('active');
      currentColor = swatch.getAttribute('data-color') || defaultValues.color;
      updateDisplay();
    });
  });

  // Reset button
  if (btnReset) {
    btnReset.addEventListener('click', () => {
      if (inputName) inputName.value = defaultValues.name;
      if (inputRole) inputRole.value = defaultValues.role;
      if (inputEmail) inputEmail.value = defaultValues.email;
      if (inputPhone) inputPhone.value = defaultValues.phone;
      if (inputWebsite) inputWebsite.value = defaultValues.website;
      if (inputAddress) inputAddress.value = defaultValues.address;
      
      currentColor = defaultValues.color;
      currentLogo = defaultValues.logo;

      colorSwatches.forEach(s => {
        s.classList.toggle('active', s.getAttribute('data-color') === defaultValues.color);
      });
      logoPillButtons.forEach(b => {
        b.classList.toggle('active', b.getAttribute('data-logo-declination') === defaultValues.logo);
      });

      updateDisplay();
      showFeedback('Valeurs réinitialisées au standard officiel SOURX.');
    });
  }

  function showFeedback(msg) {
    if (!copyFeedback) return;
    copyFeedback.innerHTML = msg;
    copyFeedback.style.display = 'block';
    setTimeout(() => {
      copyFeedback.style.display = 'none';
    }, 5000);
  }

  /**
   * Generates a self-contained HTML email signature table
   * with embedded Base64 PNG images for 100% offline compatibility,
   * inline styles, and full client support (Outlook, Gmail, Apple Mail, etc.).
   */
  function getPreparedHtmlForExport(useBase64 = true) {
    const data = getCurrentData();
    const logoKey = data.logo || 'monogram';
    const logoSrc = useBase64 
      ? (BASE64_ICONS[logoKey] || BASE64_ICONS.monogram)
      : `https://sourx.com${logoMap[logoKey] || logoMap.monogram}`;
    const linkedinSrc = useBase64 ? BASE64_ICONS.linkedin : 'https://sourx.com/images/signature/icon-social-linkedin.svg';
    const websiteSrc = useBase64 ? BASE64_ICONS.website : 'https://sourx.com/images/signature/icon-social-website.svg';
    const twitterSrc = useBase64 ? BASE64_ICONS.twitter : 'https://sourx.com/images/signature/icon-social-twitter.svg';
    const whatsappSrc = useBase64 ? BASE64_ICONS.whatsapp : 'https://sourx.com/images/signature/icon-social-whatsapp.svg';
    const emailWhiteSrc = useBase64 ? BASE64_ICONS.email_white : 'https://sourx.com/images/signature/icon-email-white.png';
    const phoneWhiteSrc = useBase64 ? BASE64_ICONS.phone_white : 'https://sourx.com/images/signature/icon-phone-white.png';
    const websiteWhiteSrc = useBase64 ? BASE64_ICONS.website_white : 'https://sourx.com/images/signature/icon-website-white.png';
    const locationWhiteSrc = useBase64 ? BASE64_ICONS.location_white : 'https://sourx.com/images/signature/icon-location-white.png';

    const cardBgColor = data.color || '#012e5c';
    const logoWidth = logoKey === 'monogram' ? 130 : 155;

    return `<table id="sourxSigTable" cellpadding="0" cellspacing="0" border="0" style="font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif; border-collapse: separate; border-spacing: 0; border: 1px solid #d8e2ea; border-radius: 14px; overflow: hidden; background-color: #ffffff; max-width: 630px; width: 100%; box-shadow: 0 4px 16px rgba(1, 46, 92, 0.06);">
  <tr>
    <!-- LEFT: White Logo Box -->
    <td id="sigLeftCell" align="center" valign="middle" style="background-color: #ffffff; width: 185px; min-width: 170px; max-width: 200px; padding: 18px 16px; border-top-left-radius: 13px; border-bottom-left-radius: 13px; vertical-align: middle; text-align: center; border-right: 1px solid #edf2f7;">
      <a href="https://sourx.com" target="_blank" style="text-decoration: none; display: block; text-align: center;">
        <img id="dispLogoImg" src="${logoSrc}" alt="SOURX EMEA" width="${logoWidth}" style="display: block; margin: 0 auto; border: 0; max-width: ${logoWidth}px; height: auto;" />
      </a>
    </td>

    <!-- RIGHT: Colored Background (SOURX Navy by default) -->
    <td id="sigRightCell" valign="middle" style="background-color: ${cardBgColor}; padding: 22px 24px; border-top-right-radius: 13px; border-bottom-right-radius: 13px; vertical-align: middle;">
      <table cellpadding="0" cellspacing="0" border="0" style="width: 100%; border-collapse: collapse;">
        <tr>
          <!-- Sub-column 1: Identity & Social Badges -->
          <td valign="middle" style="vertical-align: middle; padding-right: 20px;">
            <div id="dispName" style="font-size: 19px; font-weight: 700; color: #ffffff; letter-spacing: -0.015em; line-height: 1.25; margin-bottom: 3px;">
              ${escapeXml(data.name)}
            </div>
            <div id="dispRole" style="font-size: 12.5px; color: #d0e1f4; font-weight: 400; line-height: 1.35; margin-bottom: 14px;">
              ${escapeXml(data.role)}
            </div>
            
            <!-- Row of 4 Circular White Badges -->
            <table cellpadding="0" cellspacing="0" border="0" style="border-collapse: separate; border-spacing: 0;">
              <tr>
                <td align="center" valign="middle" style="padding-right: 9px;">
                  <a href="https://linkedin.com/company/sourx" target="_blank" style="text-decoration: none; display: inline-block; line-height: 0;">
                    <img src="${linkedinSrc}" alt="LinkedIn" width="32" height="32" style="display: block; border: 0; width: 32px; height: 32px;" />
                  </a>
                </td>
                <td align="center" valign="middle" style="padding-right: 9px;">
                  <a href="https://sourx.com" target="_blank" style="text-decoration: none; display: inline-block; line-height: 0;">
                    <img src="${websiteSrc}" alt="Web" width="32" height="32" style="display: block; border: 0; width: 32px; height: 32px;" />
                  </a>
                </td>
                <td align="center" valign="middle" style="padding-right: 9px;">
                  <a href="https://twitter.com/sourx" target="_blank" style="text-decoration: none; display: inline-block; line-height: 0;">
                    <img src="${twitterSrc}" alt="X / Twitter" width="32" height="32" style="display: block; border: 0; width: 32px; height: 32px;" />
                  </a>
                </td>
                <td align="center" valign="middle">
                  <a href="https://wa.me/442081239177" target="_blank" style="text-decoration: none; display: inline-block; line-height: 0;">
                    <img src="${whatsappSrc}" alt="WhatsApp" width="32" height="32" style="display: block; border: 0; width: 32px; height: 32px;" />
                  </a>
                </td>
              </tr>
            </table>
          </td>

          <!-- Sub-column 2: Divider Line -->
          <td valign="middle" style="width: 1px; padding: 0 20px 0 0; vertical-align: middle;">
            <div style="width: 1px; height: 96px; background-color: rgba(255, 255, 255, 0.22); font-size: 1px; line-height: 1px;">&nbsp;</div>
          </td>

          <!-- Sub-column 3: 4 Rows of Coordinates -->
          <td valign="middle" style="vertical-align: middle; white-space: nowrap;">
            <table cellpadding="0" cellspacing="0" border="0" style="font-size: 12px; line-height: 1.4; border-collapse: collapse;">
              <!-- Email -->
              <tr>
                <td style="padding: 2px 9px 2px 0; vertical-align: middle; width: 18px; text-align: center;">
                  <img src="${emailWhiteSrc}" alt="Email" width="15" height="15" style="display: block; border: 0; width: 15px; height: 15px;" />
                </td>
                <td style="padding: 2px 0; vertical-align: middle;">
                  <a href="mailto:${escapeXml(data.email)}" style="color: #ffffff; text-decoration: none; font-weight: 400; font-size: 12px;">${escapeXml(data.email)}</a>
                </td>
              </tr>
              <!-- Phone -->
              <tr>
                <td style="padding: 2px 9px 2px 0; vertical-align: middle; width: 18px; text-align: center;">
                  <img src="${phoneWhiteSrc}" alt="Phone" width="15" height="15" style="display: block; border: 0; width: 15px; height: 15px;" />
                </td>
                <td style="padding: 2px 0; vertical-align: middle;">
                  <a href="tel:${escapeXml(data.phone).replace(/\\s+/g, '')}" style="color: #ffffff; text-decoration: none; font-weight: 400; font-size: 12px;">${escapeXml(data.phone)}</a>
                </td>
              </tr>
              <!-- Website -->
              <tr>
                <td style="padding: 2px 9px 2px 0; vertical-align: middle; width: 18px; text-align: center;">
                  <img src="${websiteWhiteSrc}" alt="Web" width="15" height="15" style="display: block; border: 0; width: 15px; height: 15px;" />
                </td>
                <td style="padding: 2px 0; vertical-align: middle;">
                  <a href="${data.website.startsWith('http') ? escapeXml(data.website) : 'https://' + escapeXml(data.website)}" target="_blank" style="color: #ffffff; text-decoration: none; font-weight: 400; font-size: 12px;">${escapeXml(data.website)}</a>
                </td>
              </tr>
              <!-- Address / Hubs -->
              <tr>
                <td style="padding: 2px 9px 2px 0; vertical-align: middle; width: 18px; text-align: center;">
                  <img src="${locationWhiteSrc}" alt="Office" width="15" height="15" style="display: block; border: 0; width: 15px; height: 15px;" />
                </td>
                <td style="padding: 2px 0; vertical-align: middle;">
                  <span style="color: #ffffff; font-size: 11.5px; opacity: 0.95;">${escapeXml(data.address)}</span>
                </td>
              </tr>
            </table>
          </td>
        </tr>
      </table>
    </td>
  </tr>
</table>`;
  }

  /**
   * Copies the live rich text signature (with complete table layout and all icons embedded)
   * into the system clipboard so it pastes directly into Gmail, Outlook, Apple Mail, etc.
   */
  async function copyRichSignature() {
    const preparedHtml = getPreparedHtmlForExport(true);
    const data = getCurrentData();
    const plainText = `${data.name} | ${data.role}\nSOURX EMEA • Universal knowledge delivered locally\nEmail : ${data.email}\nTél : ${data.phone}\nWeb : ${data.website}\nHubs : ${data.address}`;

    let copied = false;

    // 1. Try modern async Clipboard API
    if (navigator.clipboard && window.ClipboardItem) {
      try {
        const blobHtml = new Blob([preparedHtml], { type: 'text/html' });
        const blobText = new Blob([plainText], { type: 'text/plain' });
        const item = new ClipboardItem({
          'text/html': blobHtml,
          'text/plain': blobText
        });
        await navigator.clipboard.write([item]);
        copied = true;
      } catch (err) {
        console.warn('Async clipboard write failed, falling back to selection copy:', err);
      }
    }

    // 2. Fallback / supplementary selection copy
    if (!copied) {
      const container = document.createElement('div');
      container.style.position = 'fixed';
      container.style.left = '-9999px';
      container.style.top = '0';
      container.innerHTML = preparedHtml;
      document.body.appendChild(container);

      const range = document.createRange();
      range.selectNodeContents(container);
      const selection = window.getSelection();
      selection.removeAllRanges();
      selection.addRange(range);

      try {
        copied = document.execCommand('copy');
      } catch (e) {
        console.warn('Selection copy failed:', e);
      } finally {
        selection.removeAllRanges();
        document.body.removeChild(container);
      }
    }

    return copied;
  }

  const btnDownloadPng = document.getElementById('btnDownloadPng');
  const btnDownloadSvg = document.getElementById('btnDownloadSvg');
  const btnQuickCopyDesktop = document.getElementById('btnQuickCopyDesktop');

  async function handleCopyVisualClick(btn) {
    const originalContent = btn.innerHTML;
    try {
      await copyRichSignature();
      btn.innerHTML = '<span>✓ Vue Texte &amp; Icônes Copiées !</span>';
      btn.style.backgroundColor = '#b6e82c';
      btn.style.color = '#012e5c';
      showFeedback('✓ Vue texte de la signature (avec layout bicolore et icônes) copiée ! Collez-la directement (<kbd>Cmd+V</kbd> ou <kbd>Ctrl+V</kbd>) dans votre messagerie (Gmail, Outlook, Apple Mail).');

      setTimeout(() => {
        btn.innerHTML = originalContent;
        btn.style.backgroundColor = '';
        btn.style.color = '';
      }, 2500);
    } catch (err) {
      console.warn('Copy error:', err);
      showFeedback('Veuillez copier manuellement la signature sélectionnée.');
    }
  }

  // 1. Copy Rich Text / Formatted Signature to Clipboard
  if (btnCopyVisual) {
    btnCopyVisual.addEventListener('click', () => handleCopyVisualClick(btnCopyVisual));
  }

  if (btnQuickCopyDesktop) {
    btnQuickCopyDesktop.addEventListener('click', () => handleCopyVisualClick(btnQuickCopyDesktop));
  }

  // 2. Download as Scalable Vector Graphic (SVG)
  if (btnDownloadSvg) {
    btnDownloadSvg.addEventListener('click', () => {
      const data = getCurrentData();
      const svgMarkup = generateSignatureSvg(data);
      const blob = new Blob([svgMarkup], { type: 'image/svg+xml;charset=utf-8' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `signature-sourx-${slugify(data.name)}.svg`;
      document.body.appendChild(a);
      a.click();
      a.remove();
      URL.revokeObjectURL(url);
      showFeedback('✓ Fichier vectoriel SVG téléchargé avec succès !');
    });
  }

  // 3. Download as High-Resolution Retina PNG (Image)
  if (btnDownloadPng) {
    btnDownloadPng.addEventListener('click', () => {
      const data = getCurrentData();
      const svgMarkup = generateSignatureSvg(data);
      const svgBlob = new Blob([svgMarkup], { type: 'image/svg+xml;charset=utf-8' });
      const url = URL.createObjectURL(svgBlob);
      const img = new Image();

      img.onload = () => {
        // Standard email display size — 1x scale for correct sizing in email clients
        const scale = 1;
        const canvas = document.createElement('canvas');
        canvas.width = 600 * scale;
        canvas.height = 128 * scale;
        const ctx = canvas.getContext('2d');
        
        ctx.scale(scale, scale);
        ctx.drawImage(img, 0, 0, 600, 128);

        canvas.toBlob((blob) => {
          if (!blob) return;
          const pngUrl = URL.createObjectURL(blob);
          const a = document.createElement('a');
          a.href = pngUrl;
          a.download = `signature-sourx-${slugify(data.name)}.png`;
          document.body.appendChild(a);
          a.click();
          a.remove();
          URL.revokeObjectURL(pngUrl);
          URL.revokeObjectURL(url);
          showFeedback('✓ Image PNG Haute Définition téléchargée avec succès !');
        }, 'image/png');
      };

      img.src = url;
    });
  }

  // 4. Copy Raw HTML Code to Clipboard
  if (btnCopyHtml) {
    btnCopyHtml.addEventListener('click', async () => {
      const originalText = btnCopyHtml.innerHTML;
      try {
        const rawHtml = getPreparedHtmlForExport().trim();
        await navigator.clipboard.writeText(rawHtml);

        btnCopyHtml.innerHTML = '<span>✓ Code HTML Copié !</span>';
        btnCopyHtml.style.backgroundColor = '#b6e82c';
        btnCopyHtml.style.color = '#012e5c';
        showFeedback('✓ Code source HTML (avec URLs absolues) copié dans le presse-papiers.');

        setTimeout(() => {
          btnCopyHtml.innerHTML = originalText;
          btnCopyHtml.style.backgroundColor = '';
          btnCopyHtml.style.color = '';
        }, 2500);
      } catch (err) {
        console.error('Copy HTML failed:', err);
      }
    });
  }

  function getCurrentData() {
    return {
      name: inputName?.value.trim() || defaultValues.name,
      role: inputRole?.value.trim() || defaultValues.role,
      email: inputEmail?.value.trim() || defaultValues.email,
      phone: inputPhone?.value.trim() || defaultValues.phone,
      website: inputWebsite?.value.trim() || defaultValues.website,
      address: inputAddress?.value.trim() || defaultValues.address,
      color: currentColor,
      logo: currentLogo
    };
  }

  function slugify(text) {
    return (text || 'sourx')
      .toString()
      .toLowerCase()
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g, '')
      .replace(/[^a-z0-9]+/g, '-')
      .replace(/(^-|-$)+/g, '');
  }

  function escapeXml(unsafe) {
    return String(unsafe || '')
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&apos;');
  }

  /**
   * Generates a self-contained SVG representation of the email signature
   * matching 100% the exact visual layout with green inner logo square.
   */
  function generateSignatureSvg(data) {
    const { name, role, email, phone, website, address, color, logo } = data;
    
    let logoMarkup = '';
    if (logo === 'monogram') {
      logoMarkup = `
        <g transform="translate(81, 14)">
          <rect x="-17" y="0" width="34" height="34" rx="8" fill="#012e5c"/>
          <rect x="3" y="0" width="14" height="14" rx="3" fill="#b6e82c"/>
          <g transform="translate(0, 52)">
            <text x="-2" y="0" text-anchor="middle" font-family="'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" font-size="18" font-weight="800" letter-spacing="-0.02em" fill="#012e5c">SOURX</text>
            <text x="28" y="-9" text-anchor="start" font-family="'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" font-size="6.5" font-weight="700" letter-spacing="0.08em" fill="#012e5c">EMEA</text>
          </g>
          <text x="0" y="73" text-anchor="middle" font-family="'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" font-size="6.2" font-weight="600" letter-spacing="0.005em" fill="#1e3a5f">Universal knowledge delivered locally</text>
        </g>
      `;
    } else if (logo === 'tagline') {
      logoMarkup = `
        <g transform="translate(8, 34)">
          <rect x="0" y="2" width="34" height="34" rx="8" fill="#012e5c"/>
          <rect x="20" y="2" width="14" height="14" rx="3" fill="#b6e82c"/>
          <text x="41" y="24" font-family="'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" font-size="20" font-weight="800" letter-spacing="-0.03em" fill="#012e5c">SOURX</text>
          <text x="110" y="15" font-family="'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" font-size="7" font-weight="700" letter-spacing="0.1em" fill="#012e5c">EMEA</text>
          <text x="41" y="37" font-family="'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" font-size="6.5" font-weight="500" fill="#64748b">Universal knowledge delivered locally</text>
        </g>
      `;
    } else {
      logoMarkup = `
        <g transform="translate(10, 44)">
          <rect x="0" y="2" width="34" height="34" rx="8" fill="#012e5c"/>
          <rect x="20" y="2" width="14" height="14" rx="3" fill="#b6e82c"/>
          <text x="41" y="26" font-family="'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" font-size="20" font-weight="800" letter-spacing="-0.03em" fill="#012e5c">SOURX</text>
          <text x="110" y="15" font-family="'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" font-size="7" font-weight="700" letter-spacing="0.1em" fill="#012e5c">EMEA</text>
        </g>
      `;
    }

    return `<svg width="600" height="128" viewBox="0 0 600 128" fill="none" xmlns="http://www.w3.org/2000/svg">
  <defs>
    <clipPath id="cardClip">
      <rect x="0" y="0" width="600" height="128" rx="12" ry="12"/>
    </clipPath>
    <!-- Clip for identity text to not overflow past divider -->
    <clipPath id="identityClip">
      <rect x="172" y="0" width="140" height="128"/>
    </clipPath>
  </defs>

  <!-- Card Background -->
  <g clip-path="url(#cardClip)">
    <rect x="0" y="0" width="162" height="128" fill="#FFFFFF"/>
    <rect x="162" y="0" width="438" height="128" fill="${color || '#012e5c'}"/>
    <line x1="162" y1="0" x2="162" y2="128" stroke="#edf2f7" stroke-width="1"/>
    
    <!-- LEFT: Logo -->
    ${logoMarkup}

    <!-- RIGHT: Identity text — clipped to prevent overflow past divider -->
    <g clip-path="url(#identityClip)">
      <text x="180" y="38" font-family="'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" font-size="17" font-weight="700" letter-spacing="-0.015em" fill="#FFFFFF">${escapeXml(name)}</text>
      <text x="180" y="55" font-family="'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" font-size="11" font-weight="400" fill="#d0e1f4">${escapeXml(role)}</text>
    </g>

    <!-- Social circular buttons at y=72 (bottom area of left column) -->
    <g transform="translate(180, 70)">
      <!-- LinkedIn -->
      <circle cx="11" cy="11" r="11" fill="#FFFFFF"/>
      <path d="M14.5 7.5a1 1 0 0 1 1 1v6a1 1 0 0 1-1 1H7.5a1 1 0 0 1-1-1v-6a1 1 0 0 1 1-1h7m-.25 7.75v-2.7c0-1.2-.9-1.3-1.3-1.3s-.9.2-1.1.65v-.5h-1.4v3.85h1.4v-2.25c0-.35.25-.65.65-.65s.65.25.65.65v2.25h1.1zm-4.65-4.4a.75.75 0 1 0 0-1.5.75.75 0 0 0 0 1.5m.65 4.4v-3.85H8.9v3.85h1.25z" fill="${color || '#012e5c'}"/>

      <!-- Website -->
      <g transform="translate(29, 0)">
        <circle cx="11" cy="11" r="11" fill="#FFFFFF"/>
        <circle cx="11" cy="11" r="5" stroke="${color || '#012e5c'}" stroke-width="1.2" fill="none"/>
        <line x1="6" y1="11" x2="16" y2="11" stroke="${color || '#012e5c'}" stroke-width="1.2"/>
        <path d="M11 6a7 7 0 0 1 1.8 5A7 7 0 0 1 11 16 7 7 0 0 1 9.2 11 7 7 0 0 1 11 6z" stroke="${color || '#012e5c'}" stroke-width="1.2" fill="none"/>
      </g>

      <!-- Twitter/X -->
      <g transform="translate(58, 0)">
        <circle cx="11" cy="11" r="11" fill="#FFFFFF"/>
        <path d="M14 7.5h1.7l-3.7 4.2 4.3 5.7h-3.3l-2.65-3.4-3 3.4H5.7l3.9-4.5-4.1-5.4h3.4l2.4 3.15zm-.6 8.8h.9L8.5 8.5H7.4z" fill="${color || '#012e5c'}"/>
      </g>

      <!-- WhatsApp -->
      <g transform="translate(87, 0)">
        <circle cx="11" cy="11" r="11" fill="#FFFFFF"/>
        <path d="M11 6.5C8.5 6.5 6.5 8.5 6.5 11c0 .85.23 1.65.64 2.33L6.5 16l2.74-.63c.65.33 1.39.52 2.17.52C13.9 15.89 16 13.74 16 11c0-2.76-2.24-4.5-5-4.5zm2.35 6.3c-.08.33-.57.6-.74.6-.23 0-.47.08-.73-.08-.16-.08-.4-.17-.65-.25-1.2-.5-2-1.78-2.05-1.86-.08-.08-.48-.65-.48-1.3 0-.58.32-.9.43-1.05.08-.1.24-.16.33-.16h.25c.08 0 .16 0 .24.16.08.24.32.8.32.9 0 .08.08.16 0 .25 0 .08-.08.16-.08.16-.08.08-.08.16-.16.16-.08.08-.08.08 0 .24.08.1.33.5.65.83.4.4.8.5.9.57.08.08.16.08.24 0 .08-.08.32-.33.32-.42.08-.08.16-.08.24-.08.08 0 .65.33.8.42.1.08.16.1.24.16 0 0 0 .25-.08.57z" fill="${color || '#012e5c'}"/>
      </g>
    </g>

    <!-- Divider Line — after socials end (180 + 4×29 = ~296 → divider at 316) -->
    <line x1="316" y1="18" x2="316" y2="110" stroke="rgba(255, 255, 255, 0.22)" stroke-width="1"/>

    <!-- RIGHT: 4 Rows of Coordinates (start at x=330, y=14) -->
    <g transform="translate(330, 14)">
      <!-- Email -->
      <g transform="translate(0, 0)">
        <rect x="0" y="3" width="13" height="10" rx="2" stroke="#FFFFFF" stroke-width="1.2" fill="none"/>
        <path d="M13 4.5L6.5 9 0 4.5" stroke="#FFFFFF" stroke-width="1.2" fill="none"/>
        <text x="20" y="12" font-family="'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" font-size="10.5" font-weight="400" fill="#FFFFFF">${escapeXml(email)}</text>
      </g>

      <!-- Phone -->
      <g transform="translate(0, 24)">
        <rect x="2" y="1" width="10" height="14" rx="2" stroke="#FFFFFF" stroke-width="1.2" fill="none"/>
        <circle cx="7" cy="12" r="0.7" fill="#FFFFFF"/>
        <text x="20" y="12" font-family="'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" font-size="10.5" font-weight="400" fill="#FFFFFF">${escapeXml(phone)}</text>
      </g>

      <!-- Website -->
      <g transform="translate(0, 48)">
        <circle cx="6.5" cy="8" r="6" stroke="#FFFFFF" stroke-width="1.2" fill="none"/>
        <line x1="0.5" y1="8" x2="12.5" y2="8" stroke="#FFFFFF" stroke-width="1.2"/>
        <path d="M6.5 2a9 9 0 0 1 2.4 6A9 9 0 0 1 6.5 14 9 9 0 0 1 4.1 8 9 9 0 0 1 6.5 2z" stroke="#FFFFFF" stroke-width="1.2" fill="none"/>
        <text x="20" y="12" font-family="'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" font-size="10.5" font-weight="400" fill="#FFFFFF">${escapeXml(website)}</text>
      </g>

      <!-- Address / Hubs -->
      <g transform="translate(0, 72)">
        <path d="M11.5 5.5c0 3.6-4.8 7.2-4.8 7.2S1.9 9.1 1.9 5.5a4.8 4.8 0 0 1 9.6 0z" stroke="#FFFFFF" stroke-width="1.2" fill="none"/>
        <circle cx="6.7" cy="5.5" r="1.6" stroke="#FFFFFF" stroke-width="1.2" fill="none"/>
        <text x="20" y="12" font-family="'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" font-size="10" font-weight="400" fill="#FFFFFF" opacity="0.95">${escapeXml(address)}</text>
      </g>
    </g>
  </g>

  <!-- Outer Border -->
  <rect x="0.5" y="0.5" width="599" height="127" rx="12" ry="12" fill="none" stroke="#d8e2ea" stroke-width="1"/>
</svg>`;
  }
}
